import {createRecordActions} from './record-actions.js';
import {createLogisticsController} from './logistics.js';
import {createTextileController} from './textile.js';
import {parsePrice,formatPrice} from './prices.mjs';
import {configured,getSession,login,logout,request,allItems,usersAPI,subscribe} from './client.js';
import {demoItems} from './demo.js';
import {normalize,quantity,movementBalance,csvExport} from './domain.mjs';
import {parseCSV} from './csv.mjs';
import {variantSku,modelVariants,modelIdentity,inventorySku,skuLegend,materialLegend,colorLegend,canonicalModelRows,materialCode} from './catalog.mjs';
import {displayYarnTitle} from './yarn.mjs';
import {cleanItem} from './text.mjs';
import {sourceSheets,sourceColumns,excelRows,excelCell} from './excel-view.mjs';
import {makeQuantityChange,validateQuantityChanges} from './quantity-edit.mjs';
const root=document.querySelector('#root');
const state={demo:false,profile:null,items:[],moves:[],users:[],tab:'overview',search:'',filters:{},page:1,live:'Conectando',busy:false,excelView:true,sheet:sourceSheets[0],editMode:false,quantityDrafts:{},editRequest:null};
let cleanup,poll,refreshing=false;
const textile=window.EURO_CONFIG?.textile?createTextileController({get profile(){return state.profile;},get items(){return active();},get connected(){return configured;},render:()=>render(),attachDelete:(...args)=>records.attach(...args),deleteRecord:(...args)=>records.confirm(...args),heading,modal,toast}):null;
const logistics=createLogisticsController({get profile(){return state.profile;},get items(){return active();},get moves(){return state.moves;},get demo(){return state.demo;},get connected(){return configured;},render:()=>render(),attachDelete:(...args)=>records.attach(...args),deleteRecord:(...args)=>records.confirm(...args),confirmAction:(...args)=>records.confirmAction(...args),inventoryFilterChanged:()=>{state.page=1;render();},reload:()=>load(),recordDemoMove:m=>state.moves.unshift({...m,id:crypto.randomUUID(),actor:state.profile.id,created_at:new Date().toISOString()}),addDemoItem:i=>state.items.push(i),heading,modal,toast});
const records=createRecordActions({get profile(){return state.profile;},get local(){return state.demo||!configured||!!window.EURO_CONFIG?.textilePreview;},rows(entity){if(entity==='items')return state.items;if(entity==='profiles')return state.users;const textileKeys={textile_suppliers:'suppliers',textile_yarns:'yarns',textile_colors:'colors',textile_stock:'stock',textile_requirements:'requirements',textile_photos:'photos',textile_drive_folders:'folders',textile_notifications:'notifications',textile_sync_runs:'runs'};const logisticsKeys={logistics_clients:'clients',logistics_shipments:'shipments',logistics_lines:'lines',logistics_documents:'documents'};return textileKeys[entity]?textile?.data()[textileKeys[entity]]||[]:logisticsKeys[entity]?logistics.data()[logisticsKeys[entity]]||[]:[];},async reload(){await load();await textile?.load();await logistics.load();if(state.tab==='users')state.users=await usersAPI();},render:()=>render(),heading,modal,toast});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name)=>({overview:'◫',inventory:'▤',models:'◇',prices:'$',movements:'⇄',review:'◎',users:'♧',settings:'⚙'}[name]||'↗');
const roles={admin:'Administradora',operadora:'Operadora',consulta:'Consulta'};
const admin=()=>state.profile?.role==='admin';const writer=()=>admin()||state.profile?.role==='operadora';
const active=()=>state.items.filter(r=>!r.archived);
const sum=rows=>rows.reduce((s,r)=>s+(r.quantity??0),0);
const options=(values,selected='',empty='Todos')=>`<option value="">${empty}</option>`+[...new Set(values.filter(Boolean))].sort().map(v=>`<option ${v===selected?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('');
const modelCover=r=>textile?.modelCover(r.model_code)||"";
const imageFor=r=>normalize(r.name).includes('NINA')?'/assets/nina.jpg':null;
const badge=r=>r.quantity===null?'<span class="badge amber">Sin confirmar</span>':r.quantity===0?'<span class="badge red">Agotado</span>':r.quantity<=r.min_stock?'<span class="badge amber">Stock bajo</span>':'<span class="badge green">En stock</span>';
const color=c=>{const n=normalize(c);return n.includes('NEGRO')?'#30302e':n.includes('BEIGE')?'#cbb69a':n.includes('OLIVO')?'#748268':n.includes('GUINDA')?'#713949':n.includes('MOSTAZA')?'#c79d4a':n.includes('GRIS')?'#9a9993':n.includes('ROJO')?'#ad5041':n.includes('AZUL')?'#718599':'#ded6c7';};
function toast(message,error=false){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast'+(error?' error':'');el.setAttribute('role','status');el.textContent=message;document.body.append(el);setTimeout(()=>el.remove(),6000);}
async function run(fn){if(state.busy)return;state.busy=true;document.querySelectorAll('dialog button[type=submit]').forEach(b=>b.disabled=true);try{await fn();}catch(e){toast(e.message,true);}finally{state.busy=false;document.querySelectorAll('dialog button[type=submit]').forEach(b=>b.disabled=false);}}
function loginPage(){root.innerHTML=`<main class="login"><section class="login-art"><div class="brand light">EUROALPACA<span>HECHO CON ORIGEN</span></div><div class="login-story"><p class="eyebrow">EXCELENCIA EN CADA FIBRA</p><h1>El cuidado de cada<br>prenda empieza aquí.</h1><p>Un espacio para organizar tu colección,<br>acompañar su proceso y conocer sus existencias.</p></div><span class="art-footer">PERÚ · FIBRAS NATURALES · EUROALPACA</span></section><section class="login-form"><div class="login-box"><p class="eyebrow">GESTIÓN DE INVENTARIO</p><h2>Bienvenida.</h2><p>Ingresa a tu espacio de trabajo.</p><form id="login-form"><label>Correo electrónico<input type="email" name="email" placeholder="tu.correo@empresa.com" required autocomplete="username"></label><label>Contraseña<input type="password" name="password" placeholder="Tu contraseña" required autocomplete="current-password"></label><button class="primary" ${configured?'':'disabled'}>Iniciar sesión <span>→</span></button><p id="login-error" role="alert"></p></form>${!configured?'<div class="notice">La conexión con Supabase aún no está configurada. Puedes explorar una demostración con datos de ejemplo.</div><button class="secondary full" id="demo">Explorar demostración →</button>':'<small>Tu administradora te proporcionará las credenciales.</small>'}<div class="login-bottom">EUROALPACA <span>Inventario & colección</span></div></div></section></main>`;
 document.querySelector('#demo')?.addEventListener('click',()=>{state.demo=true;state.profile={id:'demo',full_name:'Yadira',role:'admin',email:'demo@euroalpaca.example'};state.items=canonicalModelRows(structuredClone(demoItems));state.live='Demostración';textile?.seed();render();});
 document.querySelector('#login-form').onsubmit=e=>{e.preventDefault();run(async()=>{const f=new FormData(e.target);try{await login(f.get('email'),f.get('password'));await start();}catch(err){document.querySelector('#login-error').textContent=err.message;}});};
 if(window.EURO_CONFIG?.local)setupLocalLogin();
}
function setupLocalLogin(){
 const form=document.querySelector('#login-form');form.querySelector('button').disabled=false;
 const notice=document.querySelector('.login-box .notice');if(notice)notice.textContent='Vista local con el inventario importado. Ingresa con las credenciales de prueba de Yadira. Los cambios durante esta vista no alteran el archivo original.';
 form.onsubmit=e=>{e.preventDefault();run(async()=>{const f=new FormData(form);const response=await fetch('/local/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:f.get('email'),password:f.get('password')})});const result=await response.json();if(!response.ok){document.querySelector('#login-error').textContent=result.error;return;}const data=await fetch('/local/inventory').then(r=>r.json());state.demo=true;state.local=true;state.profile=data.profile;state.items=canonicalModelRows(data.items);state.moves=[];state.live='Vista local';textile?.seed();render();});};
}
async function allMovements(){let rows=[],offset=0;for(;;){const chunk=await request('movements?select=*&order=created_at,id&limit=1000&offset='+offset);rows.push(...chunk);if(chunk.length<1000)return rows.reverse();offset+=1000;}}
async function load(){if(state.demo)return;const [items,moves]=await Promise.all([allItems(),allMovements()]);state.items=canonicalModelRows(items);state.moves=moves;}
async function start(){const session=getSession();if(!session)return loginPage();try{const [profile]=await request('profiles?id=eq.'+session.user.id);if(!profile?.active)throw new Error('Tu cuenta no tiene acceso. Contacta a la administradora.');state.profile=profile;await load();await textile?.load();await logistics.load();if(window.EURO_CONFIG?.textilePreview)state.demo=true;render();cleanup=subscribe(()=>refresh(),status=>{state.live=status;const el=document.querySelector('#live');if(el)el.textContent=status;});poll=setInterval(()=>refresh(),15000);}catch(e){await logout();loginPage();toast(e.message,true);}}
async function refresh(){if(refreshing||state.editMode||document.querySelector('dialog[open]'))return;refreshing=true;try{await load();await textile?.load();await logistics.load();render();}catch(e){state.live='Sin conexión';document.querySelector('#live')?.replaceChildren(document.createTextNode('Sin conexión'));}finally{refreshing=false;}}
const nav=[['overview','Resumen'],['inventory','Inventario'],['models','Modelos'],['prices','Precios'],['movements','Movimientos'],['shipments','Clientes y envíos'],['review','Por revisar'],['users','Usuarios'],['codes','Leyenda de códigos'],['settings','Configuración'],['trash','Papelera'],...(textile?textile.nav():[])];
function render(){const rows=active();root.innerHTML=`<div class="app"><aside class="sidebar"><div class="brand">EUROALPACA<span>INVENTARIO & COLECCIÓN</span></div><div class="workspace"><span class="workspace-icon">E</span><div>Espacio de trabajo<small>EUROALPACA</small></div><span>⌄</span></div><p class="nav-label">GESTIÓN</p><nav>${nav.filter(([id])=>(admin()||!['users','settings','trash','textile','requirements','integrations','textile-history'].includes(id))).map(([id,label])=>`<button data-tab="${id}" class="nav-item ${state.tab===id?'selected':''}"><span>${icon(id)}</span>${label}${id==='review'?`<b>${rows.filter(r=>r.review_required).length}</b>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="help-box"><span>Una colección, todo bajo control.</span><small>Cada detalle cuenta.</small></div><div class="profile"><span class="avatar">${esc(state.profile.full_name?.slice(0,1)||'U')}</span><div>${esc(state.profile.full_name||state.profile.email)}<small>${roles[state.profile.role]}</small></div><button id="logout" aria-label="Cerrar sesión" title="Cerrar sesión">↪</button></div></div></aside><div class="main"><header class="topbar"><span>Espacio de trabajo <span class="slash">/</span> <b>${nav.find(n=>n[0]===state.tab)[1]}</b></span><div class="top-right"><span class="live"><i></i><span id="live">${esc(state.live)}</span></span><span class="date">${new Date().toLocaleDateString('es-PE',{day:'numeric',month:'long',year:'numeric'})}</span></div></header>${window.EURO_CONFIG?.textilePreview?'<div class="demo-bar textile-preview-banner">VERSIÓN DE PRUEBA · Las nuevas funciones usan registros de prueba. Las modificaciones de prendas durante esta visita no cambian el inventario real.</div>':state.demo?'<div class="demo-bar">DEMOSTRACIÓN · Datos de ejemplo. Los cambios se guardan solo durante esta visita.</div>':''}<main class="content">${content()}</main><footer>EUROALPACA <span>Hecho con origen. Gestionado con cuidado.</span></footer></div></div>`;bind();}
function heading(title,sub,actions=''){return `<div class="page-heading"><div><p class="eyebrow">EUROALPACA / ${nav.find(n=>n[0]===state.tab)[1].toUpperCase()}</p><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;}
function stats(){const r=active();return `<div class="stats">${[['Prendas registradas',sum(r),'Suma de cantidades conocidas','▦'],['Modelos en colección',new Set(r.map(x=>x.model_code)).size,'Códigos únicos de modelo','◇'],['Stock bajo',r.filter(x=>x.quantity!==null&&x.quantity<=x.min_stock).length,'Variantes que requieren atención','↘'],['Por revisar',r.filter(x=>x.review_required||x.quantity===null).length,'Información pendiente de validar','◎']].map(([l,n,s,i])=>`<article class="stat"><div>${l}<span>${i}</span></div><strong>${n}</strong><small>${s}</small></article>`).join('')}</div>`;}
function table(rows,compact=false){return `<div class="table-wrap"><table><thead><tr><th>Modelo / código</th><th>Material</th><th>Color</th><th>Talla</th><th>Ubicación</th><th>Existencias</th><th>Precio de venta</th><th>Disponibilidad</th><th></th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr><td><button class="product-link" data-detail="${r.id}"><span class="product-thumb">${modelCover(r)||(imageFor(r)?`<img src="${imageFor(r)}" alt="${esc(r.name)}">`:'◇')}</span><span><b title="${esc(r.name)}">${esc(r.name)}${r.model_code==="CR09"?" ? "+esc(r.category):""}</b><small>${esc(variantSku(r))}</small></span></button></td><td>${esc(r.material)}<small>${esc(r.composition)}</small></td><td><span class="color-dot" style="--swatch:${color(r.color)}"></span>${esc(r.color||'Pendiente')}</td><td><span class="size">${esc(r.size||'—')}</span></td><td>${state.tab==='inventory'?logistics.locationCell(r):esc(r.location)}</td><td class="quantity">${quantityCell(r)}<small>unidades</small></td><td class="sale-price">${esc(formatPrice(r))}</td><td>${badge(r)}</td><td><button class="row-action" data-detail="${r.id}" aria-label="Ver ${esc(r.name)}">↗</button>${admin()&&state.tab==='inventory'?`<button type="button" class="danger secondary" data-delete-item="${r.id}">Eliminar</button>`:''}</td></tr>`).join(''):`<tr><td colspan="9"><div class="empty">No hay prendas con estos filtros.<small>Prueba otra búsqueda o registra una nueva variante.</small></div></td></tr>`}</tbody></table></div>`;}
function filtered(){const rows=(state.excelView&&state.tab==='inventory'?excelRows(active(),state.sheet):active()).filter(r=>(state.tab!=='review'||r.review_required||r.quantity===null)&&(!state.search||normalize([r.name,r.sku,variantSku(r),r.model_code,r.material,r.composition,r.color,r.size,r.supplier,r.production_state].join(' ')).includes(normalize(state.search)))&&Object.entries(state.filters).every(([k,v])=>!v||(k==='price'?v==='pending'?r.sale_price==null:r.sale_price!=null:k==='stock'?v==='low'?r.quantity!==null&&r.quantity<=r.min_stock:v==='missing'?r.quantity===null:r.quantity>r.min_stock:r[k]===v)));return state.tab==='inventory'?logistics.filterInventory(rows):rows;}
function content(){if(state.tab==='trash')return records.content();if(logistics.has(state.tab))return logistics.content(state.tab);if(textile?.has(state.tab))return textile.content(state.tab);const r=active();
 if(state.tab==='prices')return pricesPage();
 if(state.tab==='codes')return heading('Material y modelo','Un código por material y modelo. Igual en todos los colores y tallas.')+`<section class="panel padded"><div class="sku-example"><strong>ACSU38</strong><p><b>AC</b> baby alpaca + algodón · <b>SU38</b> modelo Suyay</p></div><p>El código considera únicamente el material y el modelo. Los porcentajes de composición, colores y tallas se consultan en la ficha y no cambian el código.</p><h2>Materiales</h2><dl class="code-list">${Object.entries(materialLegend).map(([code,text])=>`<div><dt>${esc(code)}</dt><dd>${esc(text)}</dd></div>`).join('')}</dl><h2>Materiales y modelos registrados</h2><dl class="code-list models-code-list">${[...new Set(r.map(variantSku))].sort().map(code=>{const m=r.find(x=>variantSku(x)===code);return `<div><dt>${esc(code)}</dt><dd>${esc(m.material)} · ${esc(m.name)}</dd></div>`;}).join('')}</dl></section>`;
 if(state.tab==='overview'){const cat=[...new Set(r.map(x=>x.category))].map(c=>[c,sum(r.filter(x=>x.category===c))]).sort((a,b)=>b[1]-a[1]);return heading(`Hola, ${esc(state.profile.full_name?.split(' ')[0]||'bienvenida')}.`,'Una mirada clara a tu inventario, en un solo lugar.',`<button class="secondary" id="export">↓ Exportar</button>${writer()?'<button class="primary" id="movement">＋ Registrar movimiento</button>':''}`)+stats()+`<div class="overview-grid"><section class="panel"><div class="panel-head"><div><h2>Tu colección, en equilibrio</h2><p>Existencias por tipo de prenda</p></div><span class="tag">${sum(r)} unidades</span></div><div class="bars">${cat.map(([c,n])=>`<div class="bar-row"><span>${esc(c)}</span><div><i style="width:${Math.max(2,n/Math.max(1,...cat.map(a=>a[1]))*100)}%"></i></div><b>${n}</b></div>`).join('')}</div></section><section class="editorial"><p class="eyebrow">HECHO CON ORIGEN</p><h2>La esencia de tu<br>colección.</h2><p>De la fibra al guardarropa.<br>Cada prenda tiene una historia.</p><button data-tab="models">Explorar modelos ↗</button></section></div><section class="panel"><div class="panel-head"><div><h2>Prendas que necesitan atención</h2><p>Stock bajo o cantidades pendientes</p></div><button class="text-button" data-tab="inventory">Ver inventario →</button></div>${table(r.filter(x=>x.quantity===null||x.quantity<=x.min_stock).slice(0,5),true)}</section>`;}
 if(['inventory','review'].includes(state.tab)){const f=filtered(),max=Math.max(1,Math.ceil(f.length/12));state.page=Math.min(state.page,max);return heading(state.tab==='review'?'Cada detalle, en orden.':'Inventario de prendas',state.tab==='review'?'Revisa datos incompletos y combinaciones repetidas antes de confirmar existencias.':'Consulta, encuentra y gestiona cada variante de tu colección.',`<button class="secondary" id="export">↓ Exportar</button>${admin()?'<button class="secondary" id="toggle-edit">'+(state.editMode?'Salir de edición':'✎ Modo edición')+'</button><button class="primary" id="new-item">＋ Nueva variante</button>':''}`)+`<section class="panel inventory-panel">${inventoryControls()}${editingControls()}${state.tab==='inventory'?logistics.inventoryTools():''}<div class="filter-bar"><label class="search">⌕ <input id="search" placeholder="Buscar modelo, código, material, color…" value="${esc(state.search)}"></label><select data-filter="category" aria-label="Tipo de prenda">${options(r.map(x=>x.category),state.filters.category,'Todas las prendas')}</select><select data-filter="location" aria-label="Ubicación">${options(r.map(x=>x.location),state.filters.location,'Todas las ubicaciones')}</select><select data-filter="material" aria-label="Material">${options(r.map(x=>x.material),state.filters.material,'Todos los materiales')}</select><select data-filter="stock" aria-label="Stock"><option value="">Todo el stock</option><option value="low" ${state.filters.stock==='low'?'selected':''}>Stock bajo</option><option value="missing" ${state.filters.stock==='missing'?'selected':''}>Sin confirmar</option><option value="ok" ${state.filters.stock==='ok'?'selected':''}>En stock</option></select></div><div class="list-meta"><span>${f.length} variantes encontradas</span><button class="text-button" id="clear-filters">Limpiar filtros</button></div>${state.excelView&&state.tab==='inventory'?excelTable(f.slice((state.page-1)*12,state.page*12)):table(f.slice((state.page-1)*12,state.page*12))}<div class="pagination"><span>Mostrando ${f.length?(state.page-1)*12+1:0}–${Math.min(state.page*12,f.length)} de ${f.length}</span><div><button id="prev" class="page-button" aria-label="Página anterior" ${state.page===1?'disabled':''}>← Anterior</button><span class="page-position" aria-live="polite">Página ${state.page} de ${max}</span><button id="next" class="page-button" aria-label="Página siguiente" ${state.page===max?'disabled':''}>Siguiente →</button></div></div></section>`;}
 if(state.tab==='models'){const groups=[...new Set(r.map(x=>x.model_code))].map(code=>r.filter(x=>x.model_code===code));return heading('La colección','Cada modelo reúne sus materiales, colores, tallas y existencias.')+`<div class="model-grid">${groups.map(g=>`<button class="model-card" data-model="${g[0].model_code}"><div class="model-cover">${modelCover(g[0])|| (imageFor(g[0])?`<img src="${imageFor(g[0])}" alt="${esc(g[0].name)}">`:`<span>${esc(g[0].name.slice(0,1))}</span>`)}<b>${esc(g[0].model_code==="CR09"?"Conjunto":g[0].category)}</b></div><div class="model-body"><small>${g[0].model_code}</small><h2>${esc(g[0].name)}</h2><p>${esc(g[0].material)}</p><div class="model-colors">${[...new Set(g.map(x=>x.color))].slice(0,8).map(c=>`<i title="${esc(c)}" style="background:${color(c)}"></i>`).join('')}</div><div class="model-foot"><span>${modelVariants(g).length} variantes</span><b>${sum(g)} ${g[0].model_code==="CR09"?"piezas":"prendas"} ↗</b></div></div></button>`).join('')}</div>`;}
 if(state.tab==='movements')return heading('Movimientos','Entradas, salidas, ajustes y traslados con trazabilidad.',writer()?'<button class="primary" id="movement">＋ Registrar movimiento</button>':'')+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Modelo / código</th><th>Movimiento</th><th>Cantidad</th><th>Antes → después</th><th>Motivo / referencia</th></tr></thead><tbody>${state.moves.map(m=>{const item=state.items.find(x=>x.id===m.item_id);return `<tr><td>${new Date(m.created_at).toLocaleString('es-PE')}</td><td>${esc(item?.name||'Prenda')}<small>${esc(item?variantSku(item):'')}</small></td><td><span class="badge ${m.kind.includes('entrada')?'green':'amber'}">${esc(m.kind.replaceAll('_',' '))}</span></td><td>${m.amount}</td><td>${m.before_quantity??'—'} → ${m.after_quantity}</td><td>${esc(m.reason)}<small>${esc(m.reference)}</small></td></tr>`;}).join('')||'<tr><td colspan="6"><div class="empty">Aún no hay movimientos.<small>Los próximos cambios quedarán registrados aquí.</small></div></td></tr>'}</tbody></table></div><p class="panel-note">Se muestran los últimos 250 movimientos. El historial completo se conserva en Supabase.</p></section>`;
 if(state.tab==='users')return heading('Tu equipo','Crea credenciales y administra el acceso a EUROALPACA.','<button class="primary" id="new-user">＋ Crear usuario</button>')+`<section class="panel"><div class="panel-head"><h2>Personas con acceso</h2><button class="text-button" id="load-users">Actualizar lista ↻</button></div><div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Correo</th><th>Rol</th><th>Acceso</th><th></th></tr></thead><tbody>${state.users.filter(u=>!u.deleted_at).map(u=>`<tr><td>${esc(u.full_name)}</td><td>${esc(u.email)}</td><td><select data-role="${u.id}" ${u.id===state.profile.id?'disabled':''}>${Object.entries(roles).map(([v,l])=>`<option value="${v}" ${u.role===v?'selected':''}>${l}</option>`).join('')}</select></td><td>${u.active?'Activo':'Desactivado'}</td><td><button class="secondary" data-user-toggle="${u.id}" ${u.id===state.profile.id?'disabled':''}>${u.active?'Desactivar':'Activar'}</button>${u.id!==state.profile.id?'<button type="button" class="danger secondary" data-delete-user="'+u.id+'">Eliminar</button>':''}</td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">Carga la lista de usuarios para administrar sus accesos.</div></td></tr>'}</tbody></table></div></section>`;
 return heading('Configuración','Herramientas para mantener un inventario ordenado y confiable.')+`<div class="settings-grid"><section class="panel padded"><h2>Conexión y acceso</h2><p>${window.EURO_CONFIG?.textilePreview&&configured?'Vista de prueba conectada a Supabase.':state.demo?'Demostración sin conexión.':'Conectado a Supabase.'} Las credenciales son administradas por tu equipo.</p><ul><li>Administradora: catálogo, ajustes, usuarios y movimientos.</li><li>Operadora: consulta, entradas, salidas y traslados.</li><li>Consulta: lectura y exportación.</li></ul></section><section class="panel padded"><h2>Importar nuevas variantes</h2><p>CSV con columnas: sku, model_code, name, category, material, composition, color, color_code, size, location, supplier, min_stock.</p><p>Se importan con stock cero. Registra un ajuste inicial para confirmar existencias.</p><label class="secondary file-label">Seleccionar CSV<input type="file" id="import" accept=".csv" hidden></label><button class="text-button" id="template">Descargar plantilla ↓</button></section><section class="panel padded"><h2>Inventario de origen</h2><p>Los archivos de importación privados están en la carpeta data y supabase/seed.sql del proyecto. La web no los expone.</p><a href="https://docs.google.com/spreadsheets/d/1tpLM4RnS6_qBUkDjNbayB3JM4RhK3qLZ/edit" target="_blank" rel="noopener">Abrir inventario de Google ↗</a><p>La hoja de Google es la fuente de importación. Las actualizaciones del sistema se guardan en Supabase; no modifican la hoja automáticamente.</p></section></div>`;
}
function bind(){records.bind();logistics.bind(state.tab);textile?.bind();bindQuantityEditing();bindExcelNavigation();document.querySelectorAll('[data-edit-price]').forEach(b=>b.onclick=()=>editPrice(state.items.find(r=>r.id===b.dataset.editPrice)));document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{if(Object.keys(state.quantityDrafts).length){toast('Guarda o descarta las cantidades pendientes antes de cambiar de sección.',true);return;}state.editMode=false;state.tab=b.dataset.tab;textile?.enter(state.tab);logistics.enter(state.tab);records.enter(state.tab);state.page=1;state.search='';state.filters={};render();if(state.tab==='users')loadUsers();});document.querySelector('#logout').onclick=()=>run(async()=>{cleanup?.();clearInterval(poll);textile?.destroy();logistics.destroy();records.destroy();if(!state.demo)await logout();state.editMode=false;state.quantityDrafts={};state.demo=false;state.profile=null;state.users=[];state.moves=[];loginPage();});
 document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(state.items.find(r=>r.id===b.dataset.detail)));
 document.querySelectorAll('[data-model]').forEach(b=>b.onclick=()=>modelDetail(b.dataset.model));
 document.querySelector('#search')?.addEventListener('input',e=>{const value=e.target.value,pos=e.target.selectionStart;state.search=value;state.page=1;render();const el=document.querySelector('#search');el.focus();el.setSelectionRange(pos,pos);});
 document.querySelectorAll('[data-filter]').forEach(el=>el.onchange=()=>{state.filters[el.dataset.filter]=el.value;state.page=1;render();});
 document.querySelector('#clear-filters')?.addEventListener('click',()=>{logistics.clearLocationFilters();state.filters={};state.search='';state.page=1;render();});
 document.querySelector('#prev')?.addEventListener('click',()=>{state.page--;render();});document.querySelector('#next')?.addEventListener('click',()=>{state.page++;render();});
 document.querySelector('#export')?.addEventListener('click',()=>download(csvExport((['inventory','review','prices'].includes(state.tab)?filtered():active()).map(r=>({...r,product_code:variantSku(r)}))),'EUROALPACA-inventario.csv'));
 document.querySelector('#movement')?.addEventListener('click',()=>movement());document.querySelector('#new-item')?.addEventListener('click',()=>editItem());document.querySelector('#new-user')?.addEventListener('click',()=>userForm());document.querySelector('#load-users')?.addEventListener('click',()=>loadUsers());
 document.querySelectorAll('[data-role]').forEach(el=>el.onchange=()=>run(async()=>{await updateUser({id:el.dataset.role,role:el.value});await loadUsers();toast('Permisos actualizados');}));
 document.querySelectorAll('[data-user-toggle]').forEach(b=>b.onclick=()=>run(async()=>{const u=state.users.find(u=>u.id===b.dataset.userToggle);await updateUser({id:u.id,active:!u.active});await loadUsers();toast('Acceso actualizado');}));
 document.querySelector('#import')?.addEventListener('change',e=>importCSV(e.target.files[0]));document.querySelector('#template')?.addEventListener('click',()=>download('sku,model_code,name,category,material,composition,color,color_code,size,location,supplier,min_stock\n','EUROALPACA-plantilla.csv'));
 if(state.local){document.querySelector('.demo-bar').textContent='VISTA LOCAL · Inventario importado. Los cambios son de prueba y duran solo durante esta visita.';document.querySelector('#logout').onclick=()=>run(async()=>{await fetch('/local/logout',{method:'POST'});logistics.destroy();state.local=false;state.editMode=false;state.quantityDrafts={};state.demo=false;state.profile=null;state.items=[];state.users=[];state.moves=[];loginPage();});}
}
function download(text,name){const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function modal(title,body,wide=false){document.querySelector('dialog')?.remove();const d=document.createElement('dialog');d.className=wide?'wide':'';d.innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button class="close" aria-label="Cerrar">×</button></div>${body}`;document.body.append(d);d.querySelector('.close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d)d.close();});d.addEventListener('close',()=>d.remove());d.showModal();return d;}
function detail(r){const d=modal(r.name,`<div class="model-photo-gallery">${textile?.modelPhotos(r.model_code)||""}</div><div class="detail-top"><span class="tag">${esc(r.model_code)}</span>${badge(r)}<strong>${r.quantity??'—'} <small>prendas</small></strong></div><p class="detail-description">${esc(r.description)}</p><dl class="detail-grid">${[['Código de la prenda',variantSku(r)],['Precio de venta',formatPrice(r)],['Precio actualizado',r.price_updated_at?new Date(r.price_updated_at).toLocaleString('es-PE'):'Sin registrar'],['Tipo de prenda',r.category],['Material',r.material],['Composición',r.composition],['Nombre comercial',r.commercial_name],['Código de material',r.material_code],['Color',r.color],['Código de color',r.color_code],['Talla',r.size],['Ubicación',r.location],['Proveedor',r.supplier],['Estatus',r.status],['Estado de producción',r.production_state],['Hebras',r.threads],['Título del hilo',displayYarnTitle(r.yarn_title)],['Género',r.gender],['Peso de prenda',r.weight],['Peso de producción',r.production_weight],['Stock mínimo',r.min_stock],['Tipo de inventario',r.inventory_type]].map(([l,v])=>`<div><dt>${l}</dt><dd>${esc(v===0?0:v||'Pendiente')}</dd></div>`).join('')}</dl>${r.review_required?'<div class="notice">Esta variante requiere revisión de sus datos o de filas repetidas en el archivo original.</div>':''}<p><b>Observaciones</b><br>${esc(r.notes||'Sin observaciones')}</p>${r.source_sheet_name?'<p class="panel-note">Origen: '+esc(r.source_sheet_name)+' · fila '+esc(r.source_row)+'</p>':''}${r.source_snapshot?'<details><summary>Ver campos originales del Excel</summary><dl class="detail-grid">'+Object.entries(r.source_snapshot).map(([k,v])=>'<div><dt>'+esc(k||'Campo sin nombre')+'</dt><dd>'+esc(normalize(k)==='TITULO'?displayYarnTitle(v):v||'Sin dato')+'</dd></div>').join('')+'</dl></details>':''}<div class="dialog-actions">${admin()?'<button class="secondary" id="edit">Editar ficha</button><button class="primary" id="edit-quantity">✎ Editar cantidad</button>':''}<button type="button" class="secondary" data-log-location="${r.id}">Ver ubicación e historial</button>${writer()?'<button class="primary" id="detail-move">Registrar movimiento</button>':''}</div>`,true);textile?.hydrateImages();records.attach(d,'items',r,'prenda');logistics.bindLocations(d);d.querySelector('#edit-quantity')?.addEventListener('click',()=>{d.close();editSingleQuantity(r);});d.querySelector('#edit')?.addEventListener('click',()=>{d.close();editItem(r);});d.querySelector('#detail-move')?.addEventListener('click',()=>{d.close();movement(r);});}
function modelDetail(code){
 const rows=active().filter(r=>r.model_code===code),variants=modelVariants(rows);let selectedComponent=variants[0].component,selectedMaterial=materialCode(variants[0]),selectedColor=variants[0].color,selectedSize=variants[0].size;
 const d=modal(rows[0].name,'<div id="model-content"></div>',true);
 function paint(){const componentVariants=variants.filter(v=>v.component===selectedComponent);if(!componentVariants.some(v=>materialCode(v)===selectedMaterial))selectedMaterial=materialCode(componentVariants[0]);const materialVariants=componentVariants.filter(v=>materialCode(v)===selectedMaterial);if(!materialVariants.some(v=>v.color===selectedColor))selectedColor=materialVariants[0].color;const colorVariants=materialVariants.filter(v=>v.color===selectedColor);if(!colorVariants.some(v=>v.size===selectedSize))selectedSize=colorVariants[0].size;const v=colorVariants.find(v=>v.size===selectedSize);const sourceRows=v.items,known=sourceRows.filter(r=>r.quantity!==null),units=sum(known);d.querySelector('#model-content').innerHTML=  '<div class="model-photo-gallery">'+(textile?.modelPhotos(code)||'')+'</div><div class="model-detail-layout"><section><p class="eyebrow">'+esc(code)+'</p><p>'+esc(v.items[0].description||'')+'</p>'+(selectedComponent?'<label>Pieza del conjunto<select id="model-component">'+[...new Set(variants.map(v=>v.component))].map(c=>'<option value="'+esc(c)+'" '+(c===selectedComponent?'selected':'')+'>'+esc(c)+'</option>').join('')+'</select></label>':'')+'<label>Material<select id="model-material">'+[...new Set(componentVariants.map(v=>materialCode(v)))].map(m=>'<option value="'+esc(m)+'" '+(m===selectedMaterial?'selected':'')+'>'+esc(variants.find(v=>materialCode(v)===m).material||'Sin material registrado')+'</option>').join('')+'</select></label><div class="composition-box"><small>COMPOSICIÓN</small><strong>'+esc(v.composition||'Sin composición registrada')+'</strong></div><p class="selector-label">COLORES REGISTRADOS</p><div class="variant-options">'+[...new Set(materialVariants.map(v=>v.color))].map(c=>'<button data-color="'+esc(c)+'" class="variant-option '+(c===selectedColor?'chosen':'')+'" aria-pressed="'+(c===selectedColor)+'"><i style="background:'+color(c)+'"></i>'+esc(c||'Sin color registrado')+'</button>').join('')+'</div><p class="selector-label">TALLAS REGISTRADAS</p><div class="variant-options">'+colorVariants.map(v=>'<button data-size="'+esc(v.size)+'" class="variant-option '+(v.size===selectedSize?'chosen':'')+'" aria-pressed="'+(v.size===selectedSize)+'">'+esc(v.size==='NO CALIFICA'?'Única':v.size||'Sin talla registrada')+'</button>').join('')+'</div></section><aside class="variant-summary"><p class="eyebrow">VARIANTE SELECCIONADA</p><h3>'+esc(rows[0].name)+'</h3><p>'+esc(v.color||'Color pendiente')+' · '+esc(v.size==='NO CALIFICA'?'Única':v.size||'Talla pendiente')+'</p><div class="sku-box"><small>CÓDIGO</small><strong>'+esc(v.sku)+'</strong><div class="sku-legend">'+skuLegend(sourceRows[0]).map(part=>'<span><b>'+esc(part.code)+'</b>'+esc(part.label)+'</span>').join('')+'</div></div><div class="composition-box"><small>EXISTENCIAS REGISTRADAS</small><strong>'+units+' unidades'+(known.length<sourceRows.length?' · cantidad incompleta':'')+'</strong><p>Se conservan las filas originales. Revisa las alertas antes de confirmar disponibilidad comercial.</p></div><button class="primary full" id="selected-variant">Ver ficha de esta variante ↗</button></aside></div><section class="model-records"><h3>Registros de esta combinación</h3>'+table(sourceRows)+'</section>';
  d.querySelector('[data-record-delete]')?.remove();records.attach(d,'items',rows,'modelo y todas sus variantes');textile?.hydrateImages();d.querySelector('#model-component')?.addEventListener('change',e=>{selectedComponent=e.target.value;paint();});d.querySelector('#model-material').onchange=e=>{selectedMaterial=e.target.value;paint();};d.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{selectedColor=b.dataset.color;paint();});d.querySelectorAll('[data-size]').forEach(b=>b.onclick=()=>{selectedSize=b.dataset.size;paint();});d.querySelector('#selected-variant').onclick=()=>detail(sourceRows[0]);d.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(sourceRows.find(r=>r.id===b.dataset.detail)));
 }
 paint();
}
function field(name,label,value='',type='text',required=false){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0" step="1"':''}></label>`;}
function editItem(r){const fields=[['sku','Registro interno único'],['model_code','Código del modelo'],['name','Nombre del modelo'],['category','Tipo de prenda'],['material','Material'],['composition','Composición'],['commercial_name','Nombre comercial'],['material_code','Código de material'],['color','Color'],['color_code','Código de color'],['size','Talla'],['location','Ubicación'],['supplier','Proveedor'],['production_lot','Lote de producción'],['status','Estatus'],['production_state','Estado de producción'],['inventory_type','Tipo de inventario'],['threads','Hebras'],['yarn_title','Título del hilo'],['gender','Género'],['weight','Peso de prenda'],['production_weight','Peso de producción']];const draftId=r?.id||crypto.randomUUID();const defaults={model_code:'',sku:'',location:'Lima',status:'DISPONIBLE',production_state:'TERMINADO'};const d=modal(r?'Editar ficha':'Nueva variante',`<form id="item-form"><div class="form-grid">${fields.map(([k,l])=>k==='sku'?'<input type="hidden" name="sku" value="'+esc(r?.sku||'')+'">':field(k,l,r?.[k]??defaults[k]??'','text',['model_code','name','category','location'].includes(k))).join('')}${field('min_stock','Stock mínimo',r?.min_stock??2,'number')}<label>Precio de venta<input name="sale_price" type="number" min="0.01" max="99999999.99" step="0.01" value="${esc(r?.sale_price??'')}" placeholder="Por confirmar"></label><label>Moneda<select name="price_currency">${[['PEN','Soles (PEN)'],['USD','Dólares (USD)'],['EUR','Euros (EUR)']].map(([code,label])=>`<option value="${code}" ${code===(r?.price_currency||'PEN')?'selected':''}>${label}</option>`).join('')}</select></label><p class="span-2 panel-note">Registra el precio confirmado de esta variante. Vacío significa que aún falta confirmarlo.</p><label class="span-2">Descripción<textarea name="description">${esc(r?.description)}</textarea></label><label class="span-2">Observaciones<textarea name="notes">${esc(r?.notes)}</textarea></label><label class="checkbox"><input type="checkbox" name="review_required" ${r?.review_required?'checked':''}>Pendiente de revisión</label>${r?`<label class="checkbox"><input type="checkbox" name="archived" ${r.archived?'checked':''}>Archivar variante</label>`:''}</div><div class="notice">El código considera solo material y modelo. Cambiar porcentajes de composición, color o talla no cambia el código. Cada variante conserva sus existencias y precio.</div><button type="button" class="secondary" id="generate-sku">Asignar código de modelo</button><div class="dialog-actions"><button type="submit" class="primary">Guardar ficha</button></div></form>`,true);
 records.attach(d,'items',r,'prenda');
 function generateCodes(){const values=Object.fromEntries(new FormData(d.querySelector('form')));const matching=state.items.find(x=>normalize(x.name)===normalize(values.name)&&normalize(x.category)===normalize(values.category));const modelNumber=Math.max(0,...state.items.map(x=>Number(x.model_code.match(/\d+$/)?.[0])||0))+1;const item={...values,id:draftId,model_code:matching?.model_code||'',model_number:modelNumber};const identity=modelIdentity(item);d.querySelector('[name=model_code]').value=identity.code;d.querySelector('[name=sku]').value=inventorySku({...item,model_code:identity.code});}d.querySelector('#generate-sku').onclick=generateCodes;if(!r)d.querySelector('form').addEventListener('change',e=>{if(!['sku','model_code'].includes(e.target.name))generateCodes();});d.querySelector('form').onsubmit=e=>{e.preventDefault();run(async()=>{const f=new FormData(e.target),body=Object.fromEntries(fields.map(([k])=>[k,String(f.get(k)).trim()]));Object.assign(body,{sale_price:parsePrice(f.get('sale_price')),price_currency:f.get('price_currency'),min_stock:quantity(f.get('min_stock')),description:f.get('description'),notes:f.get('notes'),review_required:f.has('review_required'),archived:f.has('archived')});Object.assign(body,cleanItem(body));if(state.items.some(x=>x.sku===body.sku&&x.id!==r?.id))throw new Error('Ese SKU ya existe.');if(state.demo){if(r)Object.assign(r,body);else state.items.push({...body,id:draftId,quantity:0});}else if(r)await request('items?id=eq.'+r.id,{method:'PATCH',body});else await request('items',{method:'POST',body:{...body,id:draftId,quantity:0}});await load();d.close();render();toast('Ficha guardada');});};}
function movement(selected){const rows=active();if(!rows.length)return toast('Crea primero una variante.',true);const d=modal('Registrar movimiento',`<form id="move-form"><label>Prenda / variante<select name="item" required>${rows.map(r=>`<option value="${r.id}" ${selected?.id===r.id?'selected':''}>${esc(r.name)} · ${esc(r.color)} · ${esc(r.size)} · ${esc(r.location)} (${r.quantity??'sin confirmar'})</option>`).join('')}</select></label><div class="form-grid"><label>Tipo de movimiento<select name="kind"><option value="entrada">Entrada</option><option value="salida">Salida</option>${admin()?'<option value="ajuste">Ajuste: establecer cantidad final</option>':''}<option value="traslado">Traslado entre ubicaciones</option></select></label>${field('amount','Cantidad',1,'number',true)}</div><label id="dest-label" hidden>Variante de destino<select name="destination"></select></label><p class="panel-note" id="move-help">La cantidad se suma al stock actual.</p>${field('reason','Motivo','', 'text',true)}${field('reference','Documento / referencia')}<div class="dialog-actions"><button type="submit" class="primary">Confirmar movimiento</button></div></form>`);const form=d.querySelector('form');function update(){const item=rows.find(r=>r.id===form.elements.item.value),kind=form.elements.kind.value;d.querySelector('#dest-label').hidden=kind!=='traslado';form.elements.destination.innerHTML=rows.filter(r=>r.id!==item.id&&r.model_code===item.model_code&&r.material===item.material&&(item.model_code!=='CR09'||r.category===item.category)&&r.color===item.color&&r.size===item.size&&r.location!==item.location).map(r=>`<option value="${r.id}">${esc(r.location)} · ${esc(r.sku)} · ${r.quantity??'sin confirmar'}</option>`).join('');d.querySelector('#move-help').textContent=kind==='ajuste'?'Ingresa la cantidad final contada. Permite confirmar cantidades pendientes.':kind==='traslado'?'Selecciona la misma variante en otra ubicación. Crea antes la variante destino con stock cero si hace falta.':kind==='salida'?'La cantidad se resta del stock actual.':'La cantidad se suma al stock actual.';}form.elements.item.onchange=update;form.elements.kind.onchange=update;update();const requestId=crypto.randomUUID();form.onsubmit=e=>{e.preventDefault();run(async()=>{const f=new FormData(form),r=rows.find(r=>r.id===f.get('item')),kind=f.get('kind'),amount=quantity(f.get('amount')),reason=String(f.get('reason')).trim(),reference=f.get('reference');if(reason.length<3)throw new Error('Describe el motivo con al menos tres caracteres.');if(amount===null)throw new Error('Ingresa una cantidad.');if(state.demo){const before=r.quantity;if(kind==='traslado'){const to=rows.find(r=>r.id===f.get('destination'));if(!to||to.quantity===null)throw new Error('Selecciona un destino con stock confirmado.');r.quantity=movementBalance(r.quantity,'salida',amount);const b=to.quantity;to.quantity+=amount;state.moves.unshift({id:crypto.randomUUID(),item_id:to.id,kind:'traslado_entrada',amount,before_quantity:b,after_quantity:to.quantity,reason,reference,created_at:new Date().toISOString()});}else r.quantity=kind==='ajuste'?amount:movementBalance(r.quantity,kind,amount);state.moves.unshift({id:requestId,item_id:r.id,kind:kind==='traslado'?'traslado_salida':kind,amount,before_quantity:before,after_quantity:r.quantity,reason,reference,created_at:new Date().toISOString()});}else{await request('rpc/'+(kind==='traslado'?'transfer_stock':'record_movement'),{method:'POST',body:kind==='traslado'?{p_from:r.id,p_to:f.get('destination'),p_amount:amount,p_reason:reason,p_request:requestId}:{p_item:r.id,p_kind:kind,p_amount:amount,p_reason:reason,p_reference:reference,p_request:requestId}});}await load();d.close();render();toast('Movimiento registrado');});};}
async function loadUsers(){try{state.users=state.demo?[state.profile,...state.users.filter(x=>x.id!==state.profile.id)]:await usersAPI();render();}catch(e){toast(e.message,true);}}
async function updateUser(body){if(state.demo)Object.assign(state.users.find(u=>u.id===body.id),body);else await usersAPI('PATCH',body);}
function userForm(){const d=modal('Crear credenciales',`<form>${field('full_name','Nombre completo','','text',true)}${field('email','Correo electrónico','','email',true)}<label>Contraseña inicial<input name="password" type="password" required minlength="12" autocomplete="new-password"></label><small>Mínimo 12 caracteres. Entrega las credenciales directamente a la persona.</small><label>Rol<select name="role">${Object.entries(roles).map(([v,l])=>`<option value="${v}" ${v==='consulta'?'selected':''}>${l}</option>`).join('')}</select></label><div class="dialog-actions"><button type="submit" class="primary">Crear usuario</button></div></form>`);d.querySelector('form').onsubmit=e=>{e.preventDefault();run(async()=>{const b=Object.fromEntries(new FormData(e.target));if(state.demo){const {password,...safe}=b;state.users.push({...safe,id:crypto.randomUUID(),active:true});}else await usersAPI('POST',b);d.close();await loadUsers();toast('Usuario creado');});};}
async function importCSV(file){if(!file)return;try{const parsed=parseCSV((await file.text()).replace(/^\uFEFF/,''));const headers=parsed.shift().map(x=>x.trim());const allowed=['sku','model_code','name','category','material','composition','color','color_code','size','location','supplier','production_lot','min_stock'];const required=['sku','model_code','name','category','location'];if(!required.every(k=>headers.includes(k)))throw new Error('La plantilla debe incluir: '+required.join(', '));const items=parsed.filter(r=>r.some(v=>v.trim())).map(r=>{const out=Object.fromEntries(headers.map((h,i)=>[h,r[i]?.trim()||'']).filter(([k])=>allowed.includes(k)));if(!required.every(k=>out[k]))throw new Error('Hay filas sin código, modelo, tipo o ubicación.');out.min_stock=quantity(out.min_stock||2);out.quantity=0;out.review_required=true;return out;});if(items.length>500)throw new Error('Importa como máximo 500 variantes por archivo.');if(new Set(items.map(x=>x.sku)).size!==items.length||items.some(x=>state.items.some(r=>r.sku===x.sku)))throw new Error('Hay SKU repetidos o ya registrados.');const d=modal('Revisar importación',`<p>Se crearán ${items.length} variantes con stock cero. No se modifican variantes existentes.</p><p>Luego confirma cada existencia mediante un ajuste inicial.</p><div class="dialog-actions"><button id="confirm-import" class="primary">Importar ${items.length} variantes</button></div>`);d.querySelector('#confirm-import').onclick=()=>run(async()=>{if(state.demo)state.items.push(...items.map(x=>({...x,id:crypto.randomUUID(),archived:false})));else await request('items',{method:'POST',body:items});await load();d.close();render();toast('Importación completada');});}catch(e){toast(e.message,true);}}
function quantityCell(r){const draft=state.quantityDrafts[r.id];if(!state.editMode||!admin())return String(r.quantity??'—');return `<label class="quantity-field"><span class="sr-only">Cantidad de ${esc(r.name)} · ${esc(r.color)} · ${esc(r.size)} · fila ${esc(r.source_row||'nueva')}</span><input class="qty-edit ${draft?'changed':''}" data-quantity="${r.id}" type="number" min="0" max="2147483647" step="1" value="${draft?draft.after??'':r.quantity??''}" placeholder="Sin registrar" aria-invalid="${!!draft?.invalid}"></label>`;}
function inventoryControls(){if(state.tab!=='inventory')return '';return `<div class="inventory-views"><div><button id="view-excel" class="${state.excelView?'chosen':''}" aria-pressed="${state.excelView}">▦ Vista del Excel</button><button id="view-summary" class="${!state.excelView?'chosen':''}" aria-pressed="${!state.excelView}">☷ Vista resumida</button></div><span>${active().length} registros · ${sourceSheets.length} hojas del archivo</span></div>${state.excelView?`<div class="sheet-tabs" role="tablist" aria-label="Hojas del inventario">${sourceSheets.map(sheet=>`<button role="tab" data-sheet="${esc(sheet)}" aria-selected="${state.sheet===sheet}" class="${state.sheet===sheet?'chosen':''}">${esc(sheet)} <b>${excelRows(active(),sheet).length}</b></button>`).join('')}</div><p class="excel-note">Columnas y orden de filas del Excel. Las cantidades muestran el stock actual; los datos originales se conservan en la ficha.</p>`:''}`;}
function editingControls(){if(!state.editMode)return '';const drafts=Object.values(state.quantityDrafts),invalid=drafts.some(d=>d.invalid);return `<div class="quantity-edit-bar"><div><strong>✎ Modo edición de cantidades</strong><small>Escribe la cantidad final. Se comprobarán otros cambios antes de guardar.</small><span id="draft-counter">${drafts.length} cambios pendientes</span></div><div><button class="secondary" id="discard-quantities">Descartar cambios</button><button class="primary" id="save-quantities" ${!drafts.length||invalid?'disabled':''}>Guardar cantidades</button></div></div>`;}
function excelTable(rows){const columns=sourceColumns[state.sheet]||sourceColumns[sourceSheets[0]];return `<div class="excel-navigation"><span>Explora las columnas <small>Abre la ficha para ver todos los detalles.</small></span><div><button type="button" data-columns="-1" aria-label="Ver columnas anteriores">&larr; Anteriores</button><button type="button" data-columns="1" aria-label="Ver columnas siguientes">Siguientes &rarr;</button></div></div><div class="table-wrap excel-table-wrap" tabindex="0" role="region" aria-label="Inventario del Excel, usa las flechas para recorrer las columnas"><table class="excel-table"><thead><tr><th>Fila</th><th>Código de prenda</th>${columns.map(c=>`<th class="${normalize(c)==='CANTIDAD'?'quantity-column':''}">${esc(c||'N°')}</th>`).join('')}<th>Ubicación</th><th class="price-column">Precio de venta</th><th>Ficha</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr><td class="source-row">${r.source_row}</td><td class="model-code-cell">${esc(variantSku(r))}</td>${columns.map(c=>{const key=normalize(c),v=excelCell(r,c);return `<td class="${key==='CANTIDAD'?'quantity quantity-column':key.startsWith('DESCRIPCION')||key==='OBSERVACIONES'?'long-cell':''}">${key==='CANTIDAD'?quantityCell(r):'<div class="excel-cell-text" title="'+esc(v??'')+'">'+esc(v===null||v===''?'—':v)+'</div>'}</td>`;}).join('')}<td>${logistics.locationCell(r)}</td><td class="price-column sale-price">${esc(formatPrice(r))}</td><td><button class="row-action" data-detail="${r.id}" aria-label="Ver ficha de la fila ${r.source_row}">↗</button>${admin()?`<button type="button" class="danger secondary" data-delete-item="${r.id}">Eliminar</button>`:''}</td></tr>`).join(''):`<tr><td colspan="${columns.length+5}"><div class="empty">No hay filas con estos filtros.</div></td></tr>`}</tbody></table></div>`;}
function bindQuantityEditing(){
 document.querySelector('#toggle-edit')?.addEventListener('click',()=>{if(!admin())return;if(state.editMode&&Object.keys(state.quantityDrafts).length)return toast('Guarda o descarta las cantidades pendientes antes de salir.',true);state.editMode=!state.editMode;state.editRequest=crypto.randomUUID();render();});
 document.querySelector('#discard-quantities')?.addEventListener('click',()=>{state.quantityDrafts={};state.editRequest=crypto.randomUUID();render();});
 document.querySelector('#save-quantities')?.addEventListener('click',reviewQuantityChanges);
 document.querySelectorAll('[data-quantity]').forEach(input=>input.addEventListener('input',()=>{const item=state.items.find(r=>r.id===input.dataset.quantity),old=state.quantityDrafts[item.id];try{const change=makeQuantityChange(item,input.value,old?.request_id||crypto.randomUUID());if(change)state.quantityDrafts[item.id]=change;else delete state.quantityDrafts[item.id];input.setAttribute('aria-invalid','false');}catch{state.quantityDrafts[item.id]={id:item.id,before:item.quantity,after:null,invalid:true};input.setAttribute('aria-invalid','true');}input.classList.toggle('changed',!!state.quantityDrafts[item.id]);const drafts=Object.values(state.quantityDrafts);document.querySelector('#draft-counter').textContent=drafts.length+' cambios pendientes';document.querySelector('#save-quantities').disabled=!drafts.length||drafts.some(d=>d.invalid);}));
 document.querySelectorAll('[data-sheet]').forEach(b=>b.onclick=()=>{state.sheet=b.dataset.sheet;state.page=1;state.search='';state.filters={};render();});
 document.querySelector('#view-excel')?.addEventListener('click',()=>{state.excelView=true;state.page=1;state.filters={};render();});
 document.querySelector('#view-summary')?.addEventListener('click',()=>{state.excelView=false;state.page=1;state.filters={};render();});
}
async function saveQuantityChanges(changes,reason,requestId){validateQuantityChanges(changes);if(reason.trim().length<3)throw new Error('Escribe un motivo de al menos tres caracteres.');if(state.demo){for(const c of changes){const r=state.items.find(r=>r.id===c.id);if(!r||r.quantity!==c.before)throw new Error('Una cantidad cambió. Revisa el inventario.');}for(const c of changes){const r=state.items.find(r=>r.id===c.id);r.quantity=c.after;state.moves.unshift({id:crypto.randomUUID(),item_id:r.id,kind:'ajuste',amount:c.after,before_quantity:c.before,after_quantity:c.after,reason,reference:'Modo edición',created_at:new Date().toISOString()});}}else await request('rpc/apply_quantity_edits',{method:'POST',body:{p_changes:changes.map(({id,before,after})=>({id,before,after})),p_reason:reason.trim(),p_request:requestId}});await load();}
function reviewQuantityChanges(){const changes=Object.values(state.quantityDrafts);try{validateQuantityChanges(changes);}catch(e){return toast(e.message,true);}const d=modal('Guardar cantidades',`<p>Se actualizarán ${changes.length} registros y se guardará un ajuste en el historial por cada uno.</p><div class="quantity-review">${changes.map(c=>{const r=state.items.find(r=>r.id===c.id);return `<div><span>${esc(r.name)} · ${esc(r.color)} · ${esc(r.size)}<small>${esc(r.source_sheet_name)} · fila ${r.source_row||'nueva'}</small></span><strong>${c.before??'Sin registrar'} → ${c.after}</strong></div>`;}).join('')}</div><form>${field('reason','Motivo del cambio','Corrección de inventario','text',true)}<div class="dialog-actions"><button type="submit" class="primary">Confirmar y guardar</button></div></form>`,true);d.querySelector('form').onsubmit=e=>{e.preventDefault();run(async()=>{await saveQuantityChanges(changes,new FormData(e.target).get('reason'),state.editRequest||crypto.randomUUID());state.quantityDrafts={};state.editMode=false;state.editRequest=null;d.close();render();toast('Cantidades guardadas en el inventario');});};}
function editSingleQuantity(r){const requestId=crypto.randomUUID(),d=modal('Editar cantidad',`<p>${esc(r.name)} · ${esc(r.color)} · ${esc(r.size)}</p><p>Cantidad actual: <b>${r.quantity??'Sin registrar'}</b></p><form>${field('amount','Cantidad final',r.quantity??'','number',true)}${field('reason','Motivo','Corrección de inventario','text',true)}<div class="dialog-actions"><button type="submit" class="primary">Guardar cantidad</button></div></form>`);d.querySelector('form').onsubmit=e=>{e.preventDefault();run(async()=>{const f=new FormData(e.target),change=makeQuantityChange(r,f.get('amount'),requestId);if(change)await saveQuantityChanges([change],f.get('reason'),requestId);d.close();render();toast(change?'Cantidad guardada':'La cantidad ya era la indicada');});};}
if(configured&&getSession())start();else loginPage();

function bindExcelNavigation(){
 const wrap=document.querySelector('.excel-table-wrap');if(!wrap)return;
 const buttons=[...document.querySelectorAll('[data-columns]')];
 const update=()=>buttons.forEach(b=>b.disabled=Number(b.dataset.columns)<0?wrap.scrollLeft<=1:wrap.scrollLeft+wrap.clientWidth>=wrap.scrollWidth-2);
 buttons.forEach(b=>b.onclick=()=>wrap.scrollBy({left:Number(b.dataset.columns)*Math.max(160,wrap.clientWidth-260),behavior:'smooth'}));
 wrap.addEventListener('scroll',update,{passive:true});requestAnimationFrame(update);
}

function pricesPage(){
 const rows=filtered(),max=Math.max(1,Math.ceil(rows.length/12));state.page=Math.min(state.page,max);
 return heading('Precios de venta','Consulta los importes de cada prenda y actualízalos en un solo lugar.','<button class="secondary" id="export">↓ Exportar</button>')+
 '<section class="panel prices-panel"><div class="filter-bar"><label class="search">⌕ <input id="search" aria-label="Buscar en precios" placeholder="Buscar modelo, código o color…" value="'+esc(state.search)+'"></label><select data-filter="price" aria-label="Estado del precio"><option value="">Todos los precios</option><option value="pending" '+(state.filters.price==='pending'?'selected':'')+'>Por confirmar</option><option value="confirmed" '+(state.filters.price==='confirmed'?'selected':'')+'>Con precio</option></select></div><div class="list-meta"><span>'+rows.length+' registros · '+active().filter(r=>r.sale_price!=null).length+' con precio confirmado</span><button class="text-button" id="clear-filters">Limpiar filtros</button></div><table class="prices-table"><thead><tr><th>Prenda / código</th><th>Material / color</th><th>Talla / ubicación</th><th>Precio de venta</th><th></th></tr></thead><tbody>'+rows.slice((state.page-1)*12,state.page*12).map(r=>'<tr><td data-label="Prenda"><button class="price-product" data-detail="'+r.id+'"><b>'+esc(r.name)+(r.model_code==='CR09'?' / '+esc(r.category):'')+'</b><small>'+esc(variantSku(r))+'</small></button></td><td data-label="Material / color">'+esc(r.material)+'<small>'+esc(r.color||'Sin color registrado')+'</small></td><td data-label="Talla / ubicación">'+esc(r.size==='NO CALIFICA'?'Única':r.size||'Sin talla')+'<small>'+esc(r.location)+'</small></td><td data-label="Precio" class="sale-price">'+esc(formatPrice(r))+'<small>'+(r.sale_price!=null&&r.price_updated_at?esc(new Date(r.price_updated_at).toLocaleDateString('es-PE')):'Pendiente de registrar')+'</small></td><td class="price-action">'+(admin()?'<button class="secondary" data-edit-price="'+r.id+'">'+(r.sale_price==null?'＋ Agregar':'✎ Editar')+'</button>':'')+'</td></tr>').join('')+(rows.length?'':'<tr><td colspan="5"><div class="empty">No hay prendas con estos filtros.</div></td></tr>')+'</tbody></table><div class="pagination"><span>Mostrando '+(rows.length?(state.page-1)*12+1:0)+'–'+Math.min(state.page*12,rows.length)+' de '+rows.length+'</span><div><button id="prev" class="page-button" '+(state.page===1?'disabled':'')+'>← Anterior</button><span class="page-position">Página '+state.page+' de '+max+'</span><button id="next" class="page-button" '+(state.page===max?'disabled':'')+'>Siguiente →</button></div></div></section>';
}
function editPrice(r){
 if(!admin()||!r)return;
 const d=modal('Precio de venta','<p>'+esc(r.name)+' · '+esc(variantSku(r))+'</p><p class="panel-note">'+esc(r.material)+' · '+esc(r.color)+' · talla '+esc(r.size==='NO CALIFICA'?'única':r.size||'sin registrar')+' · '+esc(r.location)+'</p><form id="price-form"><label>Precio de venta<input name="sale_price" type="number" min="0.01" max="99999999.99" step="0.01" value="'+esc(r.sale_price??'')+'" placeholder="Por confirmar"></label><label>Moneda<select name="price_currency">'+[['PEN','Soles (PEN)'],['USD','Dólares (USD)'],['EUR','Euros (EUR)']].map(([code,label])=>'<option value="'+code+'" '+(code===(r.price_currency||'PEN')?'selected':'')+'>'+label+'</option>').join('')+'</select></label><p class="panel-note">El campo vacío deja el precio por confirmar. Este importe corresponde al registro seleccionado.</p><div class="dialog-actions"><button type="submit" class="primary">Guardar precio</button></div></form>');
 if(r.sale_price!=null){const b=document.createElement('button');b.type='button';b.className='danger secondary';b.id='delete-price';b.textContent='Eliminar precio';d.querySelector('.dialog-actions').prepend(b);b.onclick=()=>records.confirmAction('Eliminar precio','Se dejará el precio por confirmar. La prenda y sus existencias se conservan.',async()=>{if(state.demo)r.sale_price=null;else await request('items?id=eq.'+r.id,{method:'PATCH',body:{sale_price:null}});});}d.querySelector('form').onsubmit=e=>{e.preventDefault();run(async()=>{const f=new FormData(e.target),body={sale_price:parsePrice(f.get('sale_price')),price_currency:f.get('price_currency')};if(state.demo)Object.assign(r,body,{price_updated_at:new Date().toISOString()});else await request('items?id=eq.'+r.id,{method:'PATCH',body});await load();d.close();render();toast('Precio guardado');});};
}
